"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["87760"],{83153(e){e.exports=JSON.parse('{"id":"FIN-1242","slug":"absolute-advantage","term":"Absolute Advantage","also_known_as":[],"difficulty":"Advanced","definition":"Absolute advantage is the ability of a country, business or person to produce more of a good or service than others using the same amount of resources.","explanation":["The idea was described by Adam Smith in The Wealth of Nations in 1776. If one country can produce something more efficiently than another, it has an absolute advantage in that product.","For example, if Country A can produce 20 tonnes of wheat per worker and Country B only 10, Country A has an absolute advantage in wheat. If Country B can produce more cloth per worker than Country A, each has an absolute advantage in one product, and both can benefit by specializing and trading.","Absolute advantage is different from comparative advantage. A country may have an absolute advantage in producing everything, yet trade can still benefit both countries if each specializes in goods where its relative efficiency, or opportunity cost, is lowest. This insight, developed by David Ricardo, shows that trade can be beneficial even when one country is better at producing everything.","Comparative advantage is generally considered the more important concept for understanding patterns of trade."],"note":"","total":1725,"prev":{"slug":"abandonment-option","term":"Abandonment Option"},"next":{"slug":"absorption-costing","term":"Absorption Costing"}}')}}]);